  "subTopics": [
    {
      "id": "sub-1",
      "title": "1. Three-Bar Auction Lifecycle",
      "content": "\n          <p class=\"mb-3\">The transition from trend to reversal follows a strict 3-stage auction sequence:</p>\n          <ul class=\"list-disc pl-5 mb-4 space-y-1.5 text-xs text-gray-300\">\n            <li><strong>Bar 1 (Impulse):</strong> Large directional candle in the prevailing trend. Bears feel confident.</li>\n            <li><strong>Bar 2 (Transition / Star):</strong> Small body candle that gaps or pauses at the extreme. Sellers fail to push price lower despite maximum effort.</li>\n            <li><strong>Bar 3 (Expansion):</strong> Aggressive counter-trend candle closing deep inside the territory of Bar 1.</li>\n          </ul>\n        "
    },
    {
      "id": "sub-2",
      "title": "2. The 50% Midpoint Penetration Rule",
      "content": "\n          <p class=\"mb-3\">Bar 3 must close above the 50% midpoint of Bar 1's real body. If Bar 3 closes below the midpoint, it is classified as weak consolidation, not an institutional Morning Star.</p>\n        "
    }
  ],
  "tradeDetails": {
    "setupType": "Three-Bar Momentum Reversal",
    "instrument": "Sensex / Bank Nifty ATM Options",
    "entryTrigger": "Close of Bar 3 or crossing above Bar 3 high",
    "stopLoss": "1 tick below the lowest wick of Bar 2 (the Star)",
    "target1": "Prior swing peak (1:2 Risk to Reward)",
    "target2": "161.8% Fibonacci extension of the star structure (1:3.5 RR)",
    "riskReward": "1:3.0",
    "executionChecklist": [
      "Identified at daily/hourly support or lower VWAP band",
      "Bar 2 exhibits compressed volume or Doji shape",
      "Bar 3 closes decisively above Bar 1 midpoint",
      "Volume on Bar 3 is higher than Bar 2"
    ],
    "pitfalls": [
      "Entering on Bar 2 before confirmation is printed",
      "Trading stars with tiny Bar 3 bodies",
      "Ignoring nearby overhead moving averages"
    ]
  },
