  "subTopics": [
    {
      "id": "sub-1",
      "title": "1. The 3 Phases of Distribution",
      "content": "\n          <p class=\"mb-3\">A legitimate institutional Head & Shoulders has a clear volume signature:</p>\n          <ul class=\"list-disc pl-5 mb-4 space-y-1.5 text-xs text-gray-300\">\n            <li><strong>Left Shoulder:</strong> High volume standard trend rally.</li>\n            <li><strong>Head:</strong> Higher high in price, but LOWER volume than the Left Shoulder (Volume Divergence).</li>\n            <li><strong>Right Shoulder:</strong> Feeble upward drift on very low volume, followed by heavy volume on the Neckline breach.</li>\n          </ul>\n        "
    }
  ],
  "tradeDetails": {
    "setupType": "Distribution Breakdown",
    "instrument": "Bank Nifty / Sensex PE Options",
    "entryTrigger": "Breakout candle close below Neckline (or retest of broken Neckline)",
    "stopLoss": "1 tick above the high of the Right Shoulder",
    "target1": "100% measured move of Head-to-Neckline vertical distance",
    "target2": "Higher timeframe major demand origin (1:3.5 RR)",
    "riskReward": "1:3.4",
    "executionChecklist": [
      "Volume visibly decreases from Left Shoulder to Head to Right Shoulder",
      "RSI prints a distinct Bearish Divergence at the Head peak",
      "Breakdown candle closes with at least 80% body below Neckline",
      "No major support level immediately within 40 points of entry"
    ],
    "pitfalls": [
      "Shorting while price is still forming the Right Shoulder",
      "Ignoring up-sloping necklines (down-sloping necklines have 2x faster breakdowns)",
      "Not covering at the measured target when price hits major demand"
    ]
  },
